// Property-based tests: every public function is checked against random inputs
// generated by fast-check, which shrinks any failure to a minimal example.
//
//   npm test                         ~200 cases per property (quick)
//   npm run test:fuzz                20,000 cases per property
//   FUZZ_RUNS=100000 FUZZ_SEED=42 npm run test:fuzz   (a failure prints its seed to replay)
import { test } from "node:test";
import assert from "node:assert/strict";
import fc from "fast-check";
import {
  encode, decode, decodeHash, createDictionary, setCodegen,
  encrypt, decrypt, generateKey, isEncrypted,
} from "../src/index.js";
import { toBase64url, fromBase64url, toBase77, fromBase77, hasNativeBase64, B64, B77 } from "../src/text.js";

const RUNS = Number(process.env.FUZZ_RUNS) || 200;
const SEED = process.env.FUZZ_SEED ? Number(process.env.FUZZ_SEED) : undefined;
const opts = (runs = RUNS) => ({ numRuns: runs, seed: SEED, endOnFailure: false });
const hasWebCrypto = !!globalThis.crypto?.subtle || !!globalThis.process?.getBuiltinModule?.("node:crypto")?.webcrypto?.subtle;
const cryptoTest = (name, fn) => test(name, { skip: hasWebCrypto ? false : "no Web Crypto in this Node version" }, fn);

// ---------- generators ----------

// UTF-16 strings including lone surrogates, NUL, quotes, emoji, combining marks
const anyString = fc.oneof(
  fc.string(),
  fc.string({ unit: "binary" }),
  fc.array(fc.integer({ min: 0, max: 0xffff }), { maxLength: 12 }).map((c) => String.fromCharCode(...c)),
  fc.constantFrom("", "\u0000", "\ufeff", "\ufeffx", "\"\\", "😀", "\ud800", "\udfff", "é", "__proto__", "constructor", "0", "-1", "1e3"),
);
const anyNumber = fc.oneof(
  fc.integer(),
  fc.maxSafeInteger(),
  fc.double(), // includes NaN, ±Infinity, -0, subnormals
  fc.integer({ min: -1e9, max: 1e9 }).map((n) => n / 100), // fixed decimals
  fc.constantFrom(0, -0, 191, 192, 255, 256, 2 ** 31, 2 ** 32, 2 ** 53, -(2 ** 53), 2 ** 60, 1e300, 5e-324, Number.MAX_VALUE),
);
const key = fc.oneof(anyString, fc.constantFrom("__proto__", "constructor", "toString", "hasOwnProperty", "", "0", "1", "10", "a"));

// own enumerable data property, even for "__proto__"
const obj = (entries) => {
  const o = {};
  for (const [k, v] of entries) Object.defineProperty(o, k, { value: v, enumerable: true, writable: true, configurable: true });
  return o;
};

// a column of a table: every row draws a value of the same kind
const columnKinds = {
  smallInt: fc.integer({ min: -300, max: 300 }),
  bigInt: fc.maxSafeInteger(),
  decimal: fc.integer({ min: -1e7, max: 1e7 }).map((n) => n / 100),
  double: fc.double(),
  bool: fc.boolean(),
  enum: fc.constantFrom("Rome", "Paris", "Oslo", ""),
  constant: fc.constant("same"),
  string: anyString,
  nul: fc.constant(null),
  nested: fc.record({ x: fc.integer({ min: 0, max: 9 }), y: fc.constantFrom("a", "b") }),
  list: fc.array(fc.integer({ min: 0, max: 99 }), { maxLength: 4 }),
  mixed: fc.oneof(anyNumber, anyString, fc.boolean(), fc.constant(null)),
};
const table = fc
  .uniqueArray(fc.tuple(key, fc.constantFrom(...Object.keys(columnKinds)), fc.double({ min: 0, max: 1, noNaN: true })), {
    selector: (c) => c[0], minLength: 1, maxLength: 8,
  })
  .chain((cols) => {
    const timestamps = fc.array(fc.integer({ min: 0, max: 120_000 }), { minLength: 2, maxLength: 80 }).map((steps) => {
      let t = 1_767_225_600_000;
      return steps.map((s) => (t += s));
    });
    return timestamps.chain((ts) =>
      fc.tuple(...ts.map((t) =>
        fc.tuple(...cols.map(([, kind, missing]) => fc.tuple(columnKinds[kind], fc.double({ min: 0, max: 1, noNaN: true }).map((r) => r < missing * 0.5))))
          .map((cells) => obj([["ts", t], ...cols.flatMap(([k], j) => (cells[j][1] || k === "ts" ? [] : [[k, cells[j][0]]]))])),
      )));
  });

const { value: anyValue } = fc.letrec((tie) => ({
  value: fc.oneof({ depthSize: "small", withCrossShrink: true },
    fc.constant(null), fc.boolean(), anyNumber, anyString,
    fc.array(tie("value"), { maxLength: 6 }),
    fc.array(fc.tuple(key, tie("value")), { maxLength: 6 }).map(obj),
    table),
}));

const encodeOpts = fc.record({
  target: fc.constantFrom("hash", "query"),
  level: fc.option(fc.integer({ min: 0, max: 9 }), { nil: undefined }),
  native: fc.boolean(),
}, { requiredKeys: [] });

// expected decode result: JSON semantics, except NaN/±Infinity are kept and -0 becomes 0
function norm(v) {
  if (Object.is(v, -0)) return 0;
  if (Array.isArray(v)) return v.map(norm);
  if (v && typeof v === "object") return obj(Object.entries(v).map(([k, x]) => [k, norm(x)]));
  return v;
}

// random edits to a string: replace, insert, delete, truncate
const edits = fc.array(fc.record({
  op: fc.constantFrom("set", "ins", "del", "cut"),
  pos: fc.nat(),
  ch: fc.constantFrom(...B77, ...B64, "%", " ", "#"),
}), { minLength: 1, maxLength: 4 });
function applyEdits(s, list) {
  for (const { op, pos, ch } of list) {
    const i = pos % (s.length + 1);
    if (op === "set") s = s.slice(0, i) + ch + s.slice(i + 1);
    else if (op === "ins") s = s.slice(0, i) + ch + s.slice(i);
    else if (op === "del") s = s.slice(0, i) + s.slice(i + 1);
    else s = s.slice(0, i);
  }
  return s;
}

// a decoder given hostile input may throw, but only a proper Error, and must
// never pollute prototypes
function mustFailCleanly(fn) {
  try { fn(); } catch (e) { assert.ok(e instanceof Error, `threw a non-Error: ${String(e)}`); }
  assert.equal({}.polluted, undefined);
  assert.equal(Object.prototype.toString.call([]), "[object Array]");
}

// ---------- encode / decode ----------

test("encode → decode returns the same value (any JSON-like value, any options)", () => {
  fc.assert(fc.property(anyValue, encodeOpts, fc.boolean(), (v, o, nativeDecode) => {
    const s = encode(v, o);
    assert.deepEqual(decode(s, { native: nativeDecode }), norm(v));
  }), opts());
});

test("encode output uses only the target's URL-safe alphabet and is deterministic", () => {
  fc.assert(fc.property(anyValue, encodeOpts, (v, o) => {
    const s = encode(v, o);
    assert.match(s, o.target === "query" ? /^[A-Za-z0-9_-]+$/ : /^[A-Za-z0-9\-._~!$*+,;=:@/?]+$/);
    assert.equal(encode(v, o), s);
    assert.equal(isEncrypted(s), false);
  }), opts());
});

test("tables: every column type, missing keys, both row-builder paths agree", () => {
  fc.assert(fc.property(table, encodeOpts, (rows, o) => {
    const s = encode(rows, o);
    const a = decode(s);
    setCodegen(false);
    let b;
    try { b = decode(s); } finally { setCodegen(true); }
    assert.deepEqual(a, norm(rows));
    assert.deepEqual(b, a);
    assert.equal(JSON.stringify(b), JSON.stringify(a)); // same key order too
    for (const r of a) assert.equal(Object.getPrototypeOf(r), Object.prototype);
  }), opts());
});

test("dictionary: round-trips with it, refuses to decode without it or with another", () => {
  fc.assert(fc.property(fc.array(anyValue, { minLength: 1, maxLength: 3 }), anyValue, encodeOpts, (samples, v, o) => {
    const dict = createDictionary(...samples);
    assert.deepEqual(createDictionary(...samples), dict); // deterministic
    const s = encode(v, { ...o, dictionary: dict });
    assert.deepEqual(decode(s, { dictionary: dict }), norm(v));
    assert.throws(() => decode(s), /needs a dictionary/);
  }), opts());
});

test("decode of arbitrary strings: a clean Error or a value, never a crash or hang", () => {
  const plausible = fc.tuple(fc.constantFrom(...B64), fc.array(fc.constantFrom(...B77), { maxLength: 200 })).map(([h, b]) => h + b.join(""));
  fc.assert(fc.property(fc.oneof(plausible, fc.string(), fc.string({ unit: "binary" })), (s) => {
    mustFailCleanly(() => decode(s));
  }), opts(RUNS * 5));
});

test("decode of corrupted valid strings: a clean Error or a value, never a crash or hang", () => {
  fc.assert(fc.property(anyValue, encodeOpts, edits, (v, o, e) => {
    mustFailCleanly(() => decode(applyEdits(encode(v, o), e)));
  }), opts(RUNS * 5));
});

test("decodeHash reads location.hash, including percent-escaped links", () => {
  fc.assert(fc.property(anyValue, fc.boolean(), (v, escapeAll) => {
    const s = encode(v);
    const hash = "#" + (escapeAll ? encodeURIComponent(s) : s);
    assert.deepEqual(decodeHash(undefined, { hash }), norm(v));
  }), opts());
  assert.equal(decodeHash(undefined, { hash: "" }), null);
  assert.equal(decodeHash(undefined, { hash: "#" }), null);
});

test("isEncrypted never throws, whatever it is given", () => {
  fc.assert(fc.property(fc.anything(), (x) => { assert.equal(typeof isEncrypted(x), "boolean"); }), opts());
});

// ---------- text encodings ----------

test("base64url: any bytes round-trip; native and JS paths agree with Buffer", () => {
  fc.assert(fc.property(fc.uint8Array({ maxLength: 600 }), (b) => {
    const s = toBase64url(b, false);
    assert.equal(s, Buffer.from(b).toString("base64url"));
    assert.equal(toBase64url(b), s);
    assert.deepEqual(fromBase64url(s, false), b);
    assert.deepEqual(fromBase64url(s), b);
  }), opts());
});

test("base64url: any string either is rejected or is the one canonical encoding (both paths)", () => {
  const s64 = fc.array(fc.constantFrom(...B64, "=", "+", "/", " "), { maxLength: 40 }).map((a) => a.join(""));
  fc.assert(fc.property(s64, (s) => {
    const results = [false, hasNativeBase64].map((native) => {
      try { return toBase64url(fromBase64url(s, native), false); } catch (e) { assert.ok(e instanceof Error); return null; }
    });
    assert.equal(results[0], results[1], "JS and native paths disagree");
    if (results[0] !== null) assert.equal(results[0], s);
  }), opts(RUNS * 5));
});

test("base77: any bytes round-trip; any string is rejected or canonical", () => {
  fc.assert(fc.property(fc.uint8Array({ maxLength: 600 }), (b) => {
    const s = toBase77(b);
    assert.match(s, /^[A-Za-z0-9\-._~!$*+,;=:@/?]*$/);
    assert.deepEqual(fromBase77(s), b);
  }), opts());
  const s77 = fc.array(fc.constantFrom(...B77, "#", "%"), { maxLength: 90 }).map((a) => a.join(""));
  fc.assert(fc.property(s77, (s) => {
    let b;
    try { b = fromBase77(s); } catch (e) { assert.ok(e instanceof Error); return; }
    assert.equal(toBase77(b), s);
  }), opts(RUNS * 5));
});

// ---------- encryption ----------

const secretKey = fc.uint8Array({ minLength: 32, maxLength: 32 });
const password = fc.oneof(fc.string({ minLength: 8, maxLength: 40 }), fc.string({ unit: "binary", minLength: 8, maxLength: 20 }));

cryptoTest("encrypt → decrypt with a key returns the same value (any value, any options)", async () => {
  await fc.assert(fc.asyncProperty(anyValue, encodeOpts, secretKey, fc.boolean(), async (v, o, raw, asString) => {
    const key = asString ? toBase64url(raw, false) : raw;
    const s = await encrypt(v, { ...o, key });
    assert.equal(isEncrypted(s), true);
    assert.match(s, o.target === "query" ? /^[A-Za-z0-9_-]+$/ : /^[A-Za-z0-9\-._~!$*+,;=:@/?]+$/);
    assert.deepEqual(await decrypt(s, { key }), norm(v));
    assert.throws(() => decode(s), /encrypted/);
  }), opts());
});

cryptoTest("any edit to an encrypted string is detected", async () => {
  await fc.assert(fc.asyncProperty(anyValue, encodeOpts, secretKey, edits, async (v, o, key, e) => {
    const s = await encrypt(v, { ...o, key });
    const t = applyEdits(s, e);
    fc.pre(t !== s);
    await assert.rejects(decrypt(t, { key }), (err) => err instanceof Error);
  }), opts(RUNS * 2));
});

cryptoTest("a different key never decrypts", async () => {
  await fc.assert(fc.asyncProperty(anyValue, secretKey, secretKey, async (v, k1, k2) => {
    fc.pre(Buffer.compare(k1, k2) !== 0);
    await assert.rejects(decrypt(await encrypt(v, { key: k1 }), { key: k2 }), /cannot decrypt/);
  }), opts());
});

cryptoTest("encrypt → decrypt with a password (any Unicode password); wrong password fails", async () => {
  const runs = Math.max(10, Math.round(RUNS / 10)); // each case costs two key derivations
  await fc.assert(fc.asyncProperty(anyValue, password, password, async (v, pw, other) => {
    const s = await encrypt(v, { password: pw, iterations: 100_000 });
    assert.deepEqual(await decrypt(s, { password: pw, maxIterations: 100_000 }), norm(v));
    if (other.normalize("NFC") !== pw.normalize("NFC")) await assert.rejects(decrypt(s, { password: other }), /cannot decrypt/);
  }), opts(runs));
});

cryptoTest("generateKey: always 43 URL-safe characters, never repeats, always usable", async () => {
  const seen = new Set();
  for (let i = 0; i < Math.max(1000, RUNS * 5); i++) {
    const k = generateKey();
    assert.match(k, /^[A-Za-z0-9_-]{43}$/);
    assert.ok(!seen.has(k));
    seen.add(k);
  }
  const k = generateKey();
  assert.deepEqual(await decrypt(await encrypt({ a: 1 }, { key: k }), { key: k }), { a: 1 });
});
